import { DATA_KEY, createBackup, parseBackup } from './backup.js';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const uid = () => crypto.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const today = () => new Date().toISOString().slice(0, 10);
const dateOffset = days => { const d = new Date(); d.setDate(d.getDate() + days); return d.toISOString().slice(0,10); };
const monthKey = date => String(date || today()).slice(0,7);
const fmt = (value, currency = 'IDR', compact = false) => new Intl.NumberFormat('id-ID',{style:'currency',currency,maximumFractionDigits:currency==='IDR'?0:2,notation:compact?'compact':'standard'}).format(Number(value)||0);
const fmtDate = date => new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${date}T12:00:00`));
const fmtMonth = date => new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(`${date}-01T12:00:00`));
const n = value => Number(value) || 0;
const colors = ['#c8f36c','#ffd2cd','#cce7fb','#ffe795','#e5dcfa','#b5ead7','#ffc6e5','#dddfd2'];
