function icon(name, size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.grid}</svg>`}

const initial = () => {
  const book = 'book-main', team = 'book-team';
  const categories = [
    ['cat-food','Makanan','expense','food','#ffd2cd'],['cat-grocery','Belanja harian','expense','shopping','#ffe795'],['cat-transport','Transportasi','expense','car','#cce7fb'],['cat-home','Rumah & tagihan','expense','home','#e5dcfa'],['cat-health','Kesehatan','expense','heart','#b5ead7'],['cat-lifestyle','Gaya hidup','expense','spark','#ffc6e5'],['cat-salary','Gaji','income','bank','#c8f36c'],['cat-business','Usaha','income','wallet','#cce7fb'],['cat-other-in','Lainnya','income','coins','#e5dcfa'],['cat-coffee','Kopi & camilan','expense','food','#ffe795','cat-food']
  ].map(([id,name,type,ico,color,parentId])=>({id,name,type,icon:ico,color,parentId:parentId||null}));
  const tx = (id,days,type,amount,categoryId,accountId,note,bookId=book,toAccountId=null) => ({id,date:dateOffset(days),type,amount,currency:'IDR',categoryId,accountId,toAccountId,note,bookId,createdAt:Date.now()});
  return {version:2,books:[{id:book,name:'Pribadi',type:'personal',color:'#c8f36c',code:'PRIBADI-01',familyBookId:null},{id:team,name:'Rumah Bersama',type:'family',color:'#cce7fb',code:'RUMAH-01',familyBookId:null}],activeBookId:book,
    accounts:[{id:'acc-cash',name:'Tunai',type:'cash',currency:'IDR',opening:850000,bookId:book,color:'#ffe795'},{id:'acc-bank',name:'Bank Utama',type:'bank',currency:'IDR',opening:4500000,bookId:book,color:'#cce7fb'},{id:'acc-ewallet',name:'Dompet digital',type:'ewallet',currency:'IDR',opening:420000,bookId:book,color:'#e5dcfa'},{id:'acc-team',name:'Kas Rumah',type:'cash',currency:'IDR',opening:1200000,bookId:team,color:'#c8f36c'}],categories,
    transactions:[tx('t1',-18,'income',8500000,'cat-salary','acc-bank','Gaji bulanan'),tx('t2',-17,'expense',685000,'cat-grocery','acc-bank','Belanja bulanan'),tx('t3',-15,'expense',155000,'cat-food','acc-ewallet','Makan siang'),tx('t4',-13,'expense',97500,'cat-transport','acc-ewallet','Transportasi'),tx('t5',-10,'expense',420000,'cat-home','acc-bank','Listrik & internet'),tx('t6',-7,'expense',78000,'cat-coffee','acc-ewallet','Kopi sore'),tx('t7',-5,'income',1150000,'cat-business','acc-bank','Proyek desain'),tx('t8',-3,'transfer',500000,null,'acc-bank','Top up dompet digital',book,'acc-ewallet'),tx('t9',-2,'expense',230000,'cat-lifestyle','acc-ewallet','Bioskop & makan'),tx('t10',-1,'expense',65000,'cat-food','acc-cash','Sarapan'),tx('t11',-12,'expense',380000,'cat-grocery','acc-team','Belanja rumah',team)],
    budgets:[{id:'bud-1',bookId:book,categoryId:null,amount:4500000,month:monthKey(today())},{id:'bud-2',bookId:book,categoryId:'cat-food',amount:900000,month:monthKey(today())},{id:'bud-3',bookId:book,categoryId:'cat-grocery',amount:1100000,month:monthKey(today())},{id:'bud-4',bookId:book,categoryId:'cat-lifestyle',amount:500000,month:monthKey(today())}],
    recurring:[{id:'rec-1',bookId:book,type:'expense',amount:350000,categoryId:'cat-home',accountId:'acc-bank',note:'Langganan internet',frequency:'monthly',nextDate:dateOffset(12),endDate:''}],
    members:[{id:'m-self',bookId:book,name:'Saya',role:'owner'},{id:'m-team-self',bookId:team,name:'Saya',role:'owner'},{id:'m-andi',bookId:team,name:'Andi',role:'editor'},{id:'m-sari',bookId:team,name:'Sari',role:'viewer'}],splits:[],rates:{IDR:1,USD:16500,EUR:19300,SGD:12800,JPY:112},selectedCurrency:'IDR'};
};
function load(){try{const saved=JSON.parse(localStorage.getItem(DATA_KEY));if(saved?.version===2)return saved}catch{}return initial()}
let state=load();
if(state.isDemo===undefined)state.isDemo=true;
function freshState(){const next=initial();next.isDemo=false;next.books=next.books.slice(0,1);next.accounts=[{id:'acc-cash',name:'Tunai',type:'cash',currency:'IDR',opening:0,bookId:'book-main',color:'#ffe795'}];next.transactions=[];next.budgets=[];next.recurring=[];next.members=[{id:'m-self',bookId:'book-main',name:'Saya',role:'owner'}];next.splits=[];return next}
let ui={page:'dashboard',period:monthKey(today()),historySearch:'',historyType:'all',historyCategory:'all',historyAccount:'all',historyFrom:'',historyTo:'',calendarMonth:monthKey(today()),selectedDay:today(),reportPeriod:monthKey(today()),reportBook:'active',modal:null,txType:'expense',splitMethod:'equal',splitDraft:{}};
let pendingRestore=null;
function save(){localStorage.setItem(DATA_KEY,JSON.stringify(state))}
function toast(message){const layer=$('#toast-layer');const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('check',16)}<span>${esc(message)}</span>`;layer.append(el);setTimeout(()=>el.remove(),3300)}
function book(){return state.books.find(x=>x.id===state.activeBookId)||state.books[0]}
function accounts(bookId=state.activeBookId){return state.accounts.filter(x=>x.bookId===bookId)}
function txs(bookId=state.activeBookId){return state.transactions.filter(x=>Array.isArray(bookId)?bookId.includes(x.bookId):x.bookId===bookId)}
function category(id){return state.categories.find(x=>x.id===id)}
function account(id){return state.accounts.find(x=>x.id===id)}
function toBase(amount,currency){return n(amount)*(state.rates[currency]||1)}
function display(amount){const currency=state.selectedCurrency||'IDR';return fmt(n(amount)/(state.rates[currency]||1),currency)}
function displayCompact(amount){const currency=state.selectedCurrency||'IDR';return fmt(n(amount)/(state.rates[currency]||1),currency,true)}
function txBase(t){return toBase(t.amount,t.currency||'IDR')}
function balance(id){const a=account(id);if(!a)return 0;let total=toBase(a.opening,a.currency);for(const t of state.transactions){if(t.type==='income'&&t.accountId===id)total+=txBase(t);if(t.type==='expense'&&t.accountId===id)total-=txBase(t);if(t.type==='transfer'){if(t.accountId===id)total-=txBase(t);if(t.toAccountId===id)total+=txBase(t)}}return total}
function inPeriod(t,period=ui.period){return monthKey(t.date)===period}
function totals(bookId=state.activeBookId,period=ui.period){const list=txs(bookId).filter(t=>inPeriod(t,period));return {income:list.filter(t=>t.type==='income').reduce((a,t)=>a+txBase(t),0),expense:list.filter(t=>t.type==='expense').reduce((a,t)=>a+txBase(t),0)}}
function catSpend(categoryId,period=ui.period,bookId=state.activeBookId){return txs(bookId).filter(t=>t.type==='expense'&&inPeriod(t,period)&&(!categoryId||t.categoryId===categoryId||category(t.categoryId)?.parentId===categoryId)).reduce((a,t)=>a+txBase(t),0)}
function advanceDate(date,frequency){const d=new Date(`${date}T12:00:00`);if(frequency==='daily')d.setDate(d.getDate()+1);if(frequency==='weekly')d.setDate(d.getDate()+7);if(frequency==='biweekly')d.setDate(d.getDate()+14);if(frequency==='monthly')d.setMonth(d.getMonth()+1);if(frequency==='yearly')d.setFullYear(d.getFullYear()+1);return d.toISOString().slice(0,10)}
function materializeRecurring(){let count=0;for(const r of state.recurring){let guard=0;while(r.nextDate<=today()&&(!r.endDate||r.nextDate<=r.endDate)&&guard++<366){state.transactions.push({id:uid(),bookId:r.bookId,type:r.type,amount:r.amount,currency:account(r.accountId)?.currency||'IDR',categoryId:r.categoryId,accountId:r.accountId,toAccountId:null,note:r.note,date:r.nextDate,recurringId:r.id,createdAt:Date.now()});r.nextDate=advanceDate(r.nextDate,r.frequency);count++}}if(count){save();setTimeout(()=>toast(`${count} transaksi berulang dibuat otomatis`),100)}}
materializeRecurring();
const menu=[['dashboard','Ringkasan','grid'],['transactions','Transaksi','arrows'],['calendar','Kalender','calendar'],['budgets','Anggaran','target'],['reports','Laporan','chart'],['books','Buku kas','book'],['accounts','Rekening','wallet'],['categories','Kategori','tags'],['recurring','Berulang','repeat'],['splits','Patungan AA','users'],['backup','Backup & restore','copy']];
function navButton([id,label,ico]){return `<button class="nav-item ${ui.page===id?'active':''}" data-page="${id}">${icon(ico)}<span>${label}</span></button>`}
function shell(content) {
  const active=menu.find(m=>m[0]===ui.page)||['more','Lainnya','grid'];
  const moreActive=ui.page==='more'||menu.slice(5).some(m=>m[0]===ui.page);
  return `<div class="app-shell">
    <aside class="sidebar">
      <div class="brand" aria-label="PITIHDEN, dibuat oleh utiedev">
        <div class="brand-mark">P.</div>
        <div class="brand-copy">PITIHDEN<small>by utiedev</small></div>
      </div>
      <div class="sidebar-navigation">
        <div class="side-label">Workspace</div>
        <div class="nav-group">${menu.slice(0,5).map(navButton).join('')}</div>
        <div class="side-label">Kelola</div>
        <div class="nav-group">${menu.slice(5).map(navButton).join('')}</div>
      </div>
      <div class="sidebar-bottom">
        <div class="workspace-card"><span>BUKU KAS AKTIF</span><strong>${esc(book().name)}</strong>
          <button data-page="books">Kelola buku kas ${icon('chevron',13)}</button></div>
        <div class="creator-credit">Dibuat oleh <strong>utiedev</strong></div>
      </div>
    </aside>
    <main class="main"><header class="topbar">
      <div class="breadcrumbs">Workspace ${icon('chevron',13)} <strong>${esc(active[1])}</strong></div>
      <div class="top-actions"><div class="date-pill">${icon('calendar',15)} ${esc(fmtMonth(ui.period))}</div>
        <div class="book-select">${icon('book',15)}<select id="active-book" aria-label="Buku kas aktif">
          ${state.books.map(b=>`<option value="${esc(b.id)}" ${b.id===state.activeBookId?'selected':''}>${esc(b.name)}</option>`).join('')}
        </select></div><div class="avatar">PD</div></div>
    </header><div class="content">${content}</div></main>
  </div>
  <nav class="mobile-nav" aria-label="Navigasi utama">
    ${menu.slice(0,5).map(([id,label,ico])=>`<button data-page="${id}" class="${ui.page===id?'active':''}">${icon(ico)}<span>${label}</span></button>`).join('')}
    <button data-page="more" class="${moreActive?'active':''}">${icon('grid')}<span>Lainnya</span></button>
  </nav>`;
}
function pageHead(title,subtitle,actions='',eyebrow='PITIHDEN'){return `<div class="page-head"><div><p class="eyebrow">${esc(eyebrow)}${state.isDemo?' · DATA CONTOH':''}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`}
function action(label,modal,iconName='plus',cls='primary'){return `<button class="btn ${cls}" data-modal="${modal}">${icon(iconName)}${label}</button>`}
function iconTile(name,color){return `<span class="icon-tile" style="background:${color||'#fff'}">${icon(name)}</span>`}
function empty(title,subtitle,iconName='receipt'){return `<div class="empty"><div class="empty-icon">${icon(iconName,23)}</div><strong>${title}</strong>${subtitle}</div>`}
function chartCard(period=ui.period,bookId=state.activeBookId){const days=[];for(let i=5;i>=0;i--){const d=new Date(`${period}-01T12:00:00`);d.setMonth(d.getMonth()-i);days.push(d.toISOString().slice(0,7))}const points=days.map(m=>totals(bookId,m));const max=Math.max(1,...points.flatMap(p=>[p.income,p.expense]));return `<div class="card card-pad"><div class="card-head"><div class="card-title">${iconTile('chart','#cce7fb')}<div><h2>Arus kas</h2><span class="small-muted">6 bulan terakhir</span></div></div><button class="text-button" data-page="reports">Detail ${icon('chevron',13)}</button></div><div class="chart-wrap">${points.map((p,i)=>`<div class="bar-col"><div class="bar-pair"><div class="bar income" title="Pemasukan ${fmt(p.income)}" style="height:${Math.max(2,p.income/max*100)}%"></div><div class="bar expense" title="Pengeluaran ${fmt(p.expense)}" style="height:${Math.max(2,p.expense/max*100)}%"></div></div><span class="bar-label">${new Intl.DateTimeFormat('id-ID',{month:'short'}).format(new Date(`${days[i]}-01T12:00:00`))}</span></div>`).join('')}</div><div class="legend"><span><i class="income"></i>Pemasukan</span><span><i class="expense"></i>Pengeluaran</span></div></div>`}
function breakdown(period=ui.period,bookId=state.activeBookId){const map=new Map();for(const t of txs(bookId).filter(t=>t.type==='expense'&&inPeriod(t,period))){const c=category(t.categoryId), key=c?.parentId||t.categoryId||'other';map.set(key,(map.get(key)||0)+txBase(t))}return [...map].map(([id,amount])=>({id,amount,c:category(id)})).sort((a,b)=>b.amount-a.amount)}
function donutCard(period=ui.period,bookId=state.activeBookId){const entries=breakdown(period,bookId).slice(0,5), total=entries.reduce((a,x)=>a+x.amount,0);let at=0;const slices=entries.map((e,i)=>{const start=at;at+=e.amount/(total||1)*100;return `${e.c?.color||colors[i]} ${start}% ${at}%`});return `<div class="card card-pad"><div class="card-head"><div class="card-title">${iconTile('target','#ffe795')}<h2>Ke mana uangmu?</h2></div><button class="text-button" data-page="reports">Laporan ${icon('chevron',13)}</button></div>${entries.length?`<div class="donut-layout"><div class="donut" style="background:conic-gradient(${slices.join(',')})"><div class="donut-hole"><div><small>Total keluar</small><strong>${displayCompact(total)}</strong></div></div></div><div class="cat-legend">${entries.map(e=>`<div class="cat-legend-row"><span class="dot" style="background:${e.c?.color||'#ddd'}"></span><span>${esc(e.c?.name||'Lainnya')}</span><strong>${Math.round(e.amount/total*100)}%</strong></div>`).join('')}</div></div>`:empty('Belum ada pengeluaran','Tambahkan transaksi untuk melihat komposisinya.','chart')}</div>`}
function txRow(t){const c=category(t.categoryId),a=account(t.accountId),isTransfer=t.type==='transfer', label=isTransfer?`${a?.name||'Rekening'} → ${account(t.toAccountId)?.name||'Rekening'}`:(t.note||c?.name||'Transaksi');return `<div class="transaction-row"><div class="tx-icon" style="background:${isTransfer?'#dfe8fb':c?.color||'#e6e9df'}">${icon(isTransfer?'exchange':c?.icon||(t.type==='income'?'income':'expense'),17)}</div><div class="tx-main"><strong>${esc(label)}</strong><small>${esc(c?.name||(isTransfer?'Transfer':'Lainnya'))} · ${fmtDate(t.date)}</small></div><div class="tx-amount ${t.type}">${t.type==='expense'?'-':t.type==='income'?'+':''}${display(txBase(t))}</div></div>`}
function recentCard(){const list=txs().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt).slice(0,5);return `<div class="card card-pad"><div class="card-head"><div class="card-title">${iconTile('receipt','#e5dcfa')}<h2>Transaksi terbaru</h2></div><button class="text-button" data-page="transactions">Semua ${icon('chevron',13)}</button></div>${list.length?list.map(txRow).join(''):empty('Belum ada transaksi','Mulai dengan mencatat pemasukan atau pengeluaran.')}</div>`}
function budgetProgress(b,period=ui.period){const spent=catSpend(b.categoryId,period,b.bookId),ratio=spent/(b.amount||1);return `<div><div class="budget-top"><strong>${esc(category(b.categoryId)?.name||'Total pengeluaran')}</strong><span>${displayCompact(spent)} / ${displayCompact(b.amount)}</span></div><div class="progress ${ratio>=1?'over':ratio>=.8?'warn':''}"><div style="width:${Math.min(100,ratio*100)}%"></div></div></div>`}
function budgetCard(){const list=state.budgets.filter(b=>b.bookId===state.activeBookId&&b.month===ui.period).slice(0,4);return `<div class="card card-pad"><div class="card-head"><div class="card-title">${iconTile('target','#ffd2cd')}<h2>Anggaran bulan ini</h2></div><button class="text-button" data-page="budgets">Kelola ${icon('chevron',13)}</button></div>${list.length?`<div class="budget-list">${list.map(b=>budgetProgress(b)).join('')}</div>`:empty('Belum ada anggaran','Tetapkan batas pengeluaran bulanan.','target')}</div>`}
function dashboard(){const total=totals(), net=total.income-total.expense, all=accounts().reduce((a,x)=>a+balance(x.id),0), budget=state.budgets.find(b=>b.bookId===state.activeBookId&&b.month===ui.period&&!b.categoryId);return `${pageHead('Uang lebih jelas.','Semua yang penting tentang keuanganmu, dalam satu pandangan.',`${action('Catat transaksi','transaction','plus')}<button class="btn" data-modal="transfer">${icon('exchange')} Transfer</button>`,'Selamat datang kembali')}<div class="landing-banner"><div><strong>Kelola uang tanpa ribet ✳</strong><p>Catat hari ini, pahami polanya, dan ambil keputusan yang lebih tenang.</p></div><button class="btn primary" data-page="transactions">Lihat riwayat ${icon('chevron')}</button></div><div class="grid kpis"><div class="card kpi accent"><div class="kpi-top"><span class="kpi-label">Total saldo</span>${iconTile('wallet','#fff')}</div><div class="kpi-value">${display(all)}</div><div class="kpi-foot">Di ${accounts().length} rekening aktif</div></div><div class="card kpi blue"><div class="kpi-top"><span class="kpi-label">Pemasukan bulan ini</span>${iconTile('income','#fff')}</div><div class="kpi-value">${display(total.income)}</div><div class="kpi-foot">${esc(fmtMonth(ui.period))}</div></div><div class="card kpi pink"><div class="kpi-top"><span class="kpi-label">Pengeluaran bulan ini</span>${iconTile('expense','#fff')}</div><div class="kpi-value">${display(total.expense)}</div><div class="kpi-foot">${budget?`${Math.round(total.expense/budget.amount*100)}% dari anggaran total`:'Belum ada anggaran total'}</div></div><div class="card kpi yellow"><div class="kpi-top"><span class="kpi-label">Arus kas bersih</span>${iconTile('chart','#fff')}</div><div class="kpi-value">${net<0?'-':''}${display(Math.abs(net))}</div><div class="kpi-foot">Pemasukan dikurangi pengeluaran</div></div></div><div class="grid two-col">${chartCard()}${donutCard()}</div><div class="grid two-col section-gap">${recentCard()}${budgetCard()}</div>`}
function transactionTable(list){return list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Kategori</th><th>Rekening</th><th>Jenis</th><th style="text-align:right">Jumlah</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td>${fmtDate(t.date)}</td><td><strong>${esc(t.note||category(t.categoryId)?.name||(t.type==='transfer'?'Transfer':'Transaksi'))}</strong>${t.recurringId?' <span class="chip">Berulang</span>':''}</td><td>${esc(category(t.categoryId)?.name||'—')}</td><td>${esc(account(t.accountId)?.name||'—')}${t.toAccountId?` → ${esc(account(t.toAccountId)?.name||'—')}`:''}</td><td><span class="badge ${t.type}">${t.type==='expense'?'Pengeluaran':t.type==='income'?'Pemasukan':'Transfer'}</span></td><td class="num ${t.type==='income'?'strong-green':t.type==='expense'?'strong-red':''}">${t.type==='expense'?'-':t.type==='income'?'+':''}${display(txBase(t))}</td><td><div class="row-actions"><button class="icon-btn" title="Edit" data-edit="transaction:${t.id}">${icon('edit')}</button><button class="icon-btn" title="Hapus" data-delete="transaction:${t.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada transaksi','Coba ubah filter atau buat transaksi baru.')}
function transactions(){let list=txs().filter(t=>{if(ui.historySearch&&!`${t.note} ${category(t.categoryId)?.name} ${account(t.accountId)?.name}`.toLowerCase().includes(ui.historySearch.toLowerCase()))return false;if(ui.historyType!=='all'&&t.type!==ui.historyType)return false;if(ui.historyCategory!=='all'&&t.categoryId!==ui.historyCategory)return false;if(ui.historyAccount!=='all'&&t.accountId!==ui.historyAccount&&t.toAccountId!==ui.historyAccount)return false;if(ui.historyFrom&&t.date<ui.historyFrom)return false;if(ui.historyTo&&t.date>ui.historyTo)return false;return true}).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt);return `${pageHead('Transaksi','Cari, filter, dan kelola semua pergerakan uang.',`${action('Transaksi baru','transaction')}<button class="btn" data-modal="transfer">${icon('exchange')} Transfer</button>`)}<div class="card card-pad"><div class="toolbar"><div class="searchbox">${icon('search')}<input id="history-search" placeholder="Cari transaksi..." value="${esc(ui.historySearch)}" aria-label="Cari transaksi"></div><select id="history-type" class="select"><option value="all">Semua jenis</option><option value="expense" ${ui.historyType==='expense'?'selected':''}>Pengeluaran</option><option value="income" ${ui.historyType==='income'?'selected':''}>Pemasukan</option><option value="transfer" ${ui.historyType==='transfer'?'selected':''}>Transfer</option></select><select id="history-category" class="select"><option value="all">Semua kategori</option>${state.categories.map(c=>`<option value="${c.id}" ${ui.historyCategory===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="history-account" class="select"><option value="all">Semua rekening</option>${accounts().map(a=>`<option value="${a.id}" ${ui.historyAccount===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><input id="history-from" class="input" type="date" value="${ui.historyFrom}" title="Dari tanggal"><input id="history-to" class="input" type="date" value="${ui.historyTo}" title="Sampai tanggal"></div><div class="small-muted" style="margin-bottom:8px">${list.length} transaksi ditemukan</div>${transactionTable(list)}</div>`}
function calendar(){const first=new Date(`${ui.calendarMonth}-01T12:00:00`), start=(first.getDay()+6)%7, daysIn=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(), prevDays=new Date(first.getFullYear(),first.getMonth(),0).getDate();let cells='';for(let i=0;i<42;i++){const day=i-start+1,real=day>=1&&day<=daysIn,displayDay=day<1?prevDays+day:day>daysIn?day-daysIn:day,date=real?`${ui.calendarMonth}-${String(day).padStart(2,'0')}`:'';const daytx=real?txs().filter(t=>t.date===date):[], income=daytx.filter(t=>t.type==='income').reduce((a,t)=>a+txBase(t),0),expense=daytx.filter(t=>t.type==='expense').reduce((a,t)=>a+txBase(t),0);cells+=`<div class="day ${real?'':'outside'} ${date===ui.selectedDay?'selected':''} ${date===today()?'today':''}" ${real?`data-day="${date}"`:''}><span class="daynum">${displayDay}</span>${income?`<div class="day-stat income">+${displayCompact(income)}</div>`:''}${expense?`<div class="day-stat expense">-${displayCompact(expense)}</div>`:''}</div>`}const selected=txs().filter(t=>t.date===ui.selectedDay).sort((a,b)=>b.createdAt-a.createdAt);return `${pageHead('Kalender keuangan','Lihat pemasukan dan pengeluaran per hari.',`${action('Catat untuk tanggal ini','transaction')}`)}<div class="grid two-col"><div class="card card-pad"><div class="calendar-head"><h2>${esc(fmtMonth(ui.calendarMonth))}</h2><div class="month-controls"><button data-month="-1" aria-label="Bulan sebelumnya">${icon('left')}</button><button data-month="1" aria-label="Bulan berikutnya">${icon('chevron')}</button></div></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div></div><div class="card card-pad"><div class="card-head"><div><h2>${fmtDate(ui.selectedDay)}</h2><span class="small-muted">${selected.length} transaksi</span></div><button class="btn tiny primary" data-modal="transaction">${icon('plus')} Tambah</button></div>${selected.length?selected.map(txRow).join(''):empty('Hari ini masih kosong','Pilih hari lain atau tambahkan transaksi.','calendar')}</div></div>`}
function budgets(){const list=state.budgets.filter(b=>b.bookId===state.activeBookId&&b.month===ui.period),total=totals();return `${pageHead('Anggaran','Tentukan batas, pantau realisasi, tetap terkendali.',`${action('Buat anggaran','budget')}`)}<div class="grid kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="card kpi accent"><div class="kpi-top"><span class="kpi-label">Anggaran total</span>${iconTile('target','#fff')}</div><div class="kpi-value">${display(list.find(b=>!b.categoryId)?.amount||0)}</div><div class="kpi-foot">${esc(fmtMonth(ui.period))}</div></div><div class="card kpi pink"><div class="kpi-top"><span class="kpi-label">Sudah terpakai</span>${iconTile('expense','#fff')}</div><div class="kpi-value">${display(total.expense)}</div><div class="kpi-foot">Semua pengeluaran bulan ini</div></div><div class="card kpi blue"><div class="kpi-top"><span class="kpi-label">Sisa batas</span>${iconTile('wallet','#fff')}</div><div class="kpi-value">${display(Math.max(0,(list.find(b=>!b.categoryId)?.amount||0)-total.expense))}</div><div class="kpi-foot">Berdasarkan anggaran total</div></div></div><div class="card card-pad"><div class="card-head"><h2>Rincian anggaran</h2><span class="chip">${esc(fmtMonth(ui.period))}</span></div>${list.length?`<div class="grid two-col">${list.map(b=>`<div class="card card-pad" style="box-shadow:none"><div class="card-head"><div><h3>${esc(category(b.categoryId)?.name||'Total pengeluaran')}</h3><span class="small-muted">${Math.round(catSpend(b.categoryId,ui.period,b.bookId)/b.amount*100)}% terpakai</span></div><div class="row-actions"><button class="icon-btn" data-edit="budget:${b.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-delete="budget:${b.id}" title="Hapus">${icon('trash')}</button></div></div>${budgetProgress(b)}<div class="small-muted" style="margin-top:9px">Sisa ${display(Math.max(0,b.amount-catSpend(b.categoryId,ui.period,b.bookId)))}</div></div>`).join('')}</div>`:empty('Belum ada anggaran','Buat batas total atau per kategori untuk bulan ini.','target')}</div>`}
function reports(){const period=ui.reportPeriod,bookIds=ui.reportBook==='all'?state.books.map(b=>b.id):[state.activeBookId],all=bookIds.flatMap(id=>txs(id)).filter(t=>inPeriod(t,period)),income=all.filter(t=>t.type==='income').reduce((a,t)=>a+txBase(t),0),expense=all.filter(t=>t.type==='expense').reduce((a,t)=>a+txBase(t),0),monthly=bookIds.length===1?chartCard(period,bookIds[0]):chartCard(period,state.activeBookId),breakdownEntries=bookIds.flatMap(id=>breakdown(period,id));const grouped=new Map();breakdownEntries.forEach(e=>grouped.set(e.id,(grouped.get(e.id)||0)+e.amount));return `${pageHead('Laporan & analisis','Baca pola keuangan untuk mengambil keputusan lebih baik.','') }<div class="toolbar"><input id="report-period" class="input" type="month" value="${period}"><select id="report-book" class="select"><option value="active" ${ui.reportBook==='active'?'selected':''}>Buku kas aktif</option><option value="all" ${ui.reportBook==='all'?'selected':''}>Semua buku kas</option></select><button class="btn tiny" data-modal="rates">${icon('exchange')} Kurs mata uang</button></div><div class="report-summary"><div><span>Pemasukan</span><strong class="strong-green">${display(income)}</strong></div><div><span>Pengeluaran</span><strong class="strong-red">${display(expense)}</strong></div><div><span>Arus kas bersih</span><strong>${display(income-expense)}</strong></div></div><div class="grid two-col section-gap">${monthly}${donutCard(period,bookIds[0])}</div><div class="grid two-col section-gap"><div class="card card-pad"><div class="card-head"><h2>Pengeluaran per kategori</h2><span class="chip">${esc(fmtMonth(period))}</span></div>${grouped.size?[...grouped].sort((a,b)=>b[1]-a[1]).map(([id,amount])=>`<div class="stat-row"><span>${esc(category(id)?.name||'Lainnya')}</span><strong>${display(amount)}</strong></div>`).join(''):empty('Belum ada data','Pengeluaran akan tampil di sini.')}</div><div class="card card-pad"><div class="card-head"><h2>Ringkasan rekening</h2><span class="chip">${bookIds.length} buku kas</span></div>${state.accounts.filter(a=>bookIds.includes(a.bookId)).map(a=>`<div class="stat-row"><span>${esc(a.name)} · ${esc(state.books.find(b=>b.id===a.bookId)?.name||'')}</span><strong>${display(balance(a.id))}</strong></div>`).join('')}</div></div>`}
// Pages below extend the dashboard and reports.
function books(){const b=book(),members=state.members.filter(m=>m.bookId===b.id);return `${pageHead('Buku kas','Pisahkan konteks keuangan, kelola anggota, dan gabungkan pandangan keluarga.',action('Buku kas baru','book'))}<div class="grid three-col">${state.books.map(x=>`<div class="card feature-card" style="${x.id===b.id?'background:#f4fadf':''}"><div class="big-icon">${iconTile(x.type==='family'?'home':x.type==='team'?'users':'book',x.color)}</div><div><h2>${esc(x.name)}</h2><p>${esc(x.type)} · ${state.members.filter(m=>m.bookId===x.id).length} anggota</p></div><div class="bottom"><small>${state.transactions.filter(t=>t.bookId===x.id).length} transaksi</small><div class="row-actions"><button class="btn tiny ${x.id===b.id?'soft':'primary'}" data-switch-book="${x.id}">${x.id===b.id?'Aktif':'Buka'}</button><button class="icon-btn" data-edit="book:${x.id}" title="Edit">${icon('edit')}</button>${state.books.length>1?`<button class="icon-btn" data-delete="book:${x.id}" title="Hapus">${icon('trash')}</button>`:''}</div></div></div>`).join('')}</div><div class="grid two-col section-gap"><div class="card card-pad"><div class="card-head"><div><h2>Anggota — ${esc(b.name)}</h2><span class="small-muted">Peran di buku kas ini</span></div><button class="btn tiny primary" data-modal="member">${icon('plus')} Tambah</button></div>${members.map(m=>`<div class="transaction-row"><div class="mini-avatar">${esc(m.name.slice(0,2).toUpperCase())}</div><div class="tx-main"><strong>${esc(m.name)}</strong><small>${m.role==='owner'?'Pemilik':m.role==='editor'?'Dapat mengedit':'Hanya melihat'}</small></div><span class="badge ${m.role==='owner'?'purple':''}">${esc(m.role)}</span>${m.role!=='owner'?`<button class="icon-btn" data-delete="member:${m.id}" title="Hapus anggota">${icon('trash')}</button>`:''}</div>`).join('')}<div class="divider"></div><div class="notice">${icon('info')}Anggota dan kode undangan saat ini lokal. Kolaborasi lintas perangkat memerlukan backend dan identitas bersama.</div></div><div class="card card-pad"><div class="card-head"><h2>Ruang keluarga</h2>${iconTile('users','#cce7fb')}</div><p class="subtitle" style="margin:0 0 17px">Hubungkan dua buku kas. Data tetap terpisah, ringkasannya digabung.</p><div class="field"><label for="family-link">Buku kas pasangan</label><select id="family-link" class="select"><option value="">Tidak terhubung</option>${state.books.filter(x=>x.id!==b.id).map(x=>`<option value="${x.id}" ${b.familyBookId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${b.familyBookId?`<div class="report-summary" style="grid-template-columns:1fr 1fr;margin-top:15px"><div><span>Saldo gabungan</span><strong>${display(state.accounts.filter(a=>[b.id,b.familyBookId].includes(a.bookId)).reduce((sum,a)=>sum+balance(a.id),0))}</strong></div><div><span>Pengeluaran gabungan</span><strong>${display(totals(b.id).expense+totals(b.familyBookId).expense)}</strong></div></div>`:''}<div class="divider"></div><div class="small-muted">Kode buku kas: <strong>${esc(b.code)}</strong></div></div></div>`}
function accountsPage(){return `${pageHead('Rekening & saldo','Pantau tunai, bank, dompet digital, kartu, dan pinjaman.',`${action('Rekening baru','account')}<button class="btn" data-modal="rates">${icon('exchange')} Kurs</button>`)}<div class="grid three-col">${accounts().map(a=>`<div class="card feature-card"><div class="big-icon">${iconTile(a.type==='bank'?'bank':a.type==='card'?'card':a.type==='cash'?'coins':'wallet',a.color)}</div><div><h2>${esc(a.name)}</h2><p>${esc(({cash:'Tunai',bank:'Bank',ewallet:'Dompet digital',card:'Kartu',loan:'Pinjaman',other:'Lainnya'})[a.type]||a.type)} · ${esc(a.currency)}</p></div><div class="bottom"><div><span class="small-muted">Saldo saat ini</span><div class="account-balance">${display(balance(a.id))}</div></div><div class="row-actions"><button class="icon-btn" data-edit="account:${a.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-delete="account:${a.id}" title="Hapus">${icon('trash')}</button></div></div></div>`).join('')}<button class="card feature-card" data-modal="account" style="align-items:center;justify-content:center;border-style:dashed;text-align:center;background:#f4f7ed"><div class="big-icon">${iconTile('plus','#fff')}</div><h3>Tambah rekening</h3><p>Semua uang, satu pandangan.</p></button></div><div class="notice section-gap">${icon('info')}Saldo dihitung dari saldo awal dan transaksi. Transfer tidak mengubah total aset. Pinjaman dapat dicatat sebagai saldo awal negatif.</div>`}
function categoryRow(c){return `<div class="transaction-row"><div class="tx-icon" style="background:${c.color}">${icon(c.icon,17)}</div><div class="tx-main"><strong>${esc(c.name)}</strong><small>${state.categories.filter(x=>x.parentId===c.id).length} subkategori</small></div><div class="row-actions"><button class="icon-btn" data-edit="category:${c.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-delete="category:${c.id}" title="Hapus">${icon('trash')}</button></div></div>${state.categories.filter(x=>x.parentId===c.id).map(sub=>`<div class="transaction-row" style="padding-left:30px"><div class="tx-icon" style="background:${sub.color};width:27px;height:27px">${icon(sub.icon,13)}</div><div class="tx-main"><strong>${esc(sub.name)}</strong><small>Subkategori</small></div><div class="row-actions"><button class="icon-btn" data-edit="category:${sub.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-delete="category:${sub.id}" title="Hapus">${icon('trash')}</button></div></div>`).join('')}`}
function categoriesPage(){const cats=state.categories.filter(c=>!c.parentId);return `${pageHead('Kategori','Atur label pemasukan, pengeluaran, dan subkategori.',action('Kategori baru','category'))}<div class="grid two-col">${['expense','income'].map(type=>`<div class="card card-pad"><div class="card-head"><h2>${type==='expense'?'Pengeluaran':'Pemasukan'}</h2><span class="chip">${cats.filter(c=>c.type===type).length} kategori</span></div>${cats.filter(c=>c.type===type).map(categoryRow).join('')}</div>`).join('')}</div>`}
function recurringPage(){const list=state.recurring.filter(r=>r.bookId===state.activeBookId);return `${pageHead('Transaksi berulang','Otomatiskan transaksi rutin saat aplikasi dibuka.',action('Jadwal baru','recurring'))}<div class="card card-pad">${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Nama</th><th>Jenis</th><th>Frekuensi</th><th>Berikutnya</th><th>Rekening</th><th style="text-align:right">Jumlah</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.note)}</strong><div class="small-muted">${esc(category(r.categoryId)?.name||'—')}</div></td><td><span class="badge ${r.type}">${r.type==='income'?'Pemasukan':'Pengeluaran'}</span></td><td>${esc(({daily:'Harian',weekly:'Mingguan',biweekly:'2 mingguan',monthly:'Bulanan',yearly:'Tahunan'})[r.frequency])}</td><td>${fmtDate(r.nextDate)}</td><td>${esc(account(r.accountId)?.name||'—')}</td><td class="num">${display(toBase(r.amount,account(r.accountId)?.currency||'IDR'))}</td><td><div class="row-actions"><button class="icon-btn" data-edit="recurring:${r.id}" title="Edit">${icon('edit')}</button><button class="icon-btn" data-delete="recurring:${r.id}" title="Hapus">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada jadwal','Tambahkan pengeluaran atau pemasukan rutin.','repeat')}</div><div class="notice section-gap">${icon('info')}Jadwal jatuh tempo dibuat saat aplikasi dibuka. Tanggal yang terlewat dikejar otomatis, tanpa notifikasi latar belakang.</div>`}
function splitOwed(split){return split.shares.map(s=>({...s,paid:(split.settlements||[]).filter(x=>x.memberId===s.memberId).reduce((a,x)=>a+n(x.amount),0)}))}
function splitsPage(){const list=state.splits.filter(s=>s.bookId===state.activeBookId);return `${pageHead('Patungan AA','Bagi tagihan secara adil dan pantau siapa masih berutang.',action('Patungan baru','split'))}<div class="grid two-col">${list.length?list.map(s=>{const outstanding=splitOwed(s).filter(x=>x.memberId!==s.payerMemberId).reduce((a,x)=>a+Math.max(0,x.amount-x.paid),0);return `<div class="card feature-card"><div class="bottom"><div class="big-icon">${iconTile('users','#e5dcfa')}</div><span class="badge ${outstanding?'expense':'income'}">${outstanding?'Belum lunas':'Lunas'}</span></div><div><h2>${esc(s.title)}</h2><p>${fmtDate(s.date)} · ${s.shares.length} orang · Dibayar ${esc(state.members.find(m=>m.id===s.payerMemberId)?.name||'—')}</p></div><div class="report-summary" style="grid-template-columns:1fr 1fr"><div><span>Total tagihan</span><strong>${display(s.amount)}</strong></div><div><span>Belum lunas</span><strong>${display(outstanding)}</strong></div></div><div class="bottom"><button class="btn tiny" data-view-split="${s.id}">Lihat rincian ${icon('chevron',13)}</button><button class="icon-btn" data-delete="split:${s.id}" title="Hapus patungan">${icon('trash')}</button></div></div>`}).join(''):empty('Belum ada patungan','Bagi tagihan dengan anggota buku kas ini.','users')}</div><div class="notice section-gap">${icon('info')}Patungan juga dicatat sebagai pengeluaran pada rekening pembayar. Pelunasan dicatat sebagai pemasukan pada rekening yang dipilih.</div>`}
function morePage(){return `${pageHead('Lainnya','Seluruh alat pengelolaan PITIHDEN dalam satu tempat.')}<div class="grid three-col">${menu.slice(5).map(([id,label,ico],index)=>`<button class="card feature-card more-link" data-page="${id}"><div class="big-icon">${iconTile(ico,colors[index%colors.length])}</div><div><h2>${esc(label)}</h2><p>${esc(({books:'Kelola beberapa buku kas dan anggota.',accounts:'Lihat saldo dan mata uang.',categories:'Susun kategori dan subkategori.',recurring:'Atur transaksi rutin.',splits:'Bagi tagihan dan catat pelunasan.',backup:'Simpan atau pulihkan file JSON.'})[id]||'')}</p></div><div class="bottom"><small>Buka fitur</small>${icon('chevron',15)}</div></button>`).join('')}</div><p class="creator-credit mobile-credit">PITIHDEN dibuat oleh <strong>utiedev</strong></p>`}
function backupPage(){return `${pageHead('Backup & restore','Simpan data ke file JSON, lalu pulihkan kapan saja di browser ini.')}<div class="notice" style="margin-bottom:19px">${icon('info')}File diproses di perangkat ini. Backup dan restore tidak mengirim data ke server PITIHDEN.</div><div class="grid two-col backup-grid"><section class="card card-pad backup-card"><div class="card-head"><div class="card-title">${iconTile('copy','#c8f36c')}<h2>Backup data</h2></div></div><p class="subtitle">Unduh satu file JSON berisi seluruh buku kas, rekening, kategori, transaksi, anggaran, jadwal, anggota, patungan, dan kurs.</p><div class="backup-metrics"><div><strong>${state.books.length}</strong><span>Buku kas</span></div><div><strong>${state.transactions.length}</strong><span>Transaksi</span></div><div><strong>${state.splits.length}</strong><span>Patungan</span></div></div><button class="btn primary" data-download-backup>${icon('copy')} Unduh backup JSON</button></section><section class="card card-pad backup-card"><div class="card-head"><div class="card-title">${iconTile('repeat','#cce7fb')}<h2>Restore data</h2></div></div><p class="subtitle">Pilih file backup PITIHDEN berformat JSON. Isi file diperiksa dan diringkas sebelum mengganti data saat ini.</p><div class="notice restore-warning">${icon('info')}Restore akan menimpa seluruh data lokal di browser ini. Simpan backup terbaru terlebih dahulu.</div><input id="restore-file" class="visually-hidden" type="file" accept=".json,application/json" aria-label="Pilih file backup JSON"><label class="btn" for="restore-file">${icon('plus')} Pilih file JSON</label></section></div><div class="card card-pad section-gap"><h2>Cara kerjanya</h2><div class="backup-steps"><div><span>01</span><strong>Unduh</strong><p>File disimpan oleh browser di perangkatmu.</p></div><div><span>02</span><strong>Simpan aman</strong><p>File berisi data keuangan; jangan bagikan sembarangan.</p></div><div><span>03</span><strong>Pulihkan</strong><p>Pilih file JSON, tinjau ringkasan, lalu konfirmasi.</p></div></div></div>`}
function render(){const pages={dashboard,transactions,calendar,budgets,reports:reportsV2,books,accounts:accountsPage,categories:categoriesPage,recurring:recurringPage,splits:splitsPage,backup:backupPage,more:morePage};const demo=state.isDemo?`<div class="notice" style="margin-bottom:20px;align-items:center;background:#e5dcfa">${icon('info')}<span style="flex:1">Ini data contoh untuk menjelajahi fitur. Mulai dengan data keuangan kosong kapan saja.</span><button class="btn tiny primary" data-start-fresh>Mulai kosong</button></div>`:'';$('#app').innerHTML=shell(demo+(pages[ui.page]||dashboard)());const pill=$('.date-pill');if(pill)pill.innerHTML=`${icon('calendar',15)}<input id="global-period" type="month" value="${ui.period}" aria-label="Periode aktif">`;if(['dashboard','budgets'].includes(ui.page))$('.page-head')?.insertAdjacentHTML('afterend',`<div class="mobile-period"><label for="mobile-period">Periode</label><input id="mobile-period" class="input" type="month" value="${ui.period}"></div>`);if(ui.modal)renderModal()}
function opts(items,valueKey='id',labelKey='name',selected='',placeholder='Pilih...'){return `<option value="">${placeholder}</option>${items.map(x=>`<option value="${esc(x[valueKey])}" ${x[valueKey]===selected?'selected':''}>${esc(x[labelKey])}</option>`).join('')}`}
function field(label,name,body,cls=''){return `<div class="field ${cls}"><label for="f-${name}">${label}</label>${body}</div>`}
function input(name,type='text',value='',attrs=''){return `<input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`}
function select(name,options,attrs=''){return `<select class="select" id="f-${name}" name="${name}" ${attrs}>${options}</select>`}
function modalFrame(title,subtitle,body,submit='Simpan',wide=false){return `<div class="modal-backdrop" data-close-backdrop><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-close aria-label="Tutup">${icon('x')}</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="form-actions"><button type="button" class="btn plain" data-close>Batal</button><button type="submit" class="btn primary">${icon('check')} ${esc(submit)}</button></div></form></div></div>`}
function modalTransaction(){const t=ui.modal?.id?state.transactions.find(x=>x.id===ui.modal.id):null,type=t?.type||ui.txType,date=t?.date||(ui.page==='calendar'?ui.selectedDay:today()),acc=accounts();return modalFrame(t?'Edit transaksi':'Catat transaksi','Lengkapi detail agar laporan tetap akurat.',`<div class="segmented"><button type="button" data-txtype="expense" class="${type==='expense'?'active':''}">Pengeluaran</button><button type="button" data-txtype="income" class="${type==='income'?'active':''}">Pemasukan</button></div><input type="hidden" name="type" value="${type}"><div class="form-grid" style="margin-top:17px">${field('Jumlah','amount',input('amount','number',t?.amount||'','min="0.01" step="0.01" required'))}${field('Tanggal','date',input('date','date',date,'required'))}${field('Rekening','accountId',select('accountId',opts(acc,'id','name',t?.accountId||acc[0]?.id,'Pilih rekening'),'required'))}${field('Mata uang','currency',select('currency',['IDR','USD','EUR','SGD','JPY'].map(c=>`<option value="${c}" ${c===(t?.currency||account(t?.accountId||acc[0]?.id)?.currency||'IDR')?'selected':''}>${c}</option>`).join('')))}${field('Kategori','categoryId',select('categoryId',opts(state.categories.filter(c=>c.type===type),'id','name',t?.categoryId,'Pilih kategori'),'required'))}${field('Catatan','note',input('note','text',t?.note||'','placeholder="Contoh: makan siang"'),'span2')}</div>`,'Simpan transaksi')}
function modalTransfer(){const t=ui.modal?.id?state.transactions.find(x=>x.id===ui.modal.id):null;return modalFrame(t?'Edit transfer':'Transfer antar rekening','Pindahkan dana tanpa mengubah total aset.',`<div class="form-grid">${field('Jumlah','amount',input('amount','number',t?.amount||'','min="0.01" step="0.01" required'))}${field('Tanggal','date',input('date','date',t?.date||today(),'required'))}${field('Dari rekening','accountId',select('accountId',opts(accounts(),'id','name',t?.accountId,'Pilih sumber'),'required'))}${field('Ke rekening','toAccountId',select('toAccountId',opts(accounts(),'id','name',t?.toAccountId,'Pilih tujuan'),'required'))}${field('Catatan','note',input('note','text',t?.note||'','placeholder="Opsional"'),'span2')}</div>`,'Simpan transfer')}
function modalBudget(){const b=ui.modal?.id?state.budgets.find(x=>x.id===ui.modal.id):null;return modalFrame(b?'Edit anggaran':'Buat anggaran','Batas bulanan untuk total atau kategori tertentu.',`<div class="form-grid">${field('Bulan','month',input('month','month',b?.month||ui.period,'required'))}${field('Batas pengeluaran (IDR)','amount',input('amount','number',b?.amount||'','min="1" step="1" required'))}${field('Kategori','categoryId',select('categoryId',`<option value="">Total pengeluaran</option>${state.categories.filter(c=>c.type==='expense'&&!c.parentId).map(c=>`<option value="${c.id}" ${b?.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}`),'span2')}</div>`)}
function modalAccount(){const a=ui.modal?.id?account(ui.modal.id):null;return modalFrame(a?'Edit rekening':'Rekening baru','Saldo awal dan mata uang tetap dapat diubah.',`<div class="form-grid">${field('Nama rekening','name',input('name','text',a?.name||'','required placeholder="Contoh: Bank Utama"'),'span2')}${field('Jenis','type',select('type',[['cash','Tunai'],['bank','Bank'],['ewallet','Dompet digital'],['card','Kartu'],['loan','Pinjaman'],['other','Lainnya']].map(([id,label])=>`<option value="${id}" ${a?.type===id?'selected':''}>${label}</option>`).join('')))}${field('Mata uang','currency',select('currency',['IDR','USD','EUR','SGD','JPY'].map(c=>`<option value="${c}" ${c===(a?.currency||'IDR')?'selected':''}>${c}</option>`).join('')))}${field('Saldo awal','opening',input('opening','number',a?.opening??0,'step="0.01" required'))}${field('Warna','color',select('color',colors.map(c=>`<option value="${c}" ${c===(a?.color||colors[0])?'selected':''}>${c}</option>`).join('')))}</div>`)}
function modalCategory(){const c=ui.modal?.id?category(ui.modal.id):null;return modalFrame(c?'Edit kategori':'Kategori baru','Atur struktur kategori dan subkategori.',`<div class="form-grid">${field('Nama','name',input('name','text',c?.name||'','required'),'span2')}${field('Jenis','type',select('type',`<option value="expense" ${c?.type==='expense'?'selected':''}>Pengeluaran</option><option value="income" ${c?.type==='income'?'selected':''}>Pemasukan</option>`))}${field('Induk (opsional)','parentId',select('parentId',opts(state.categories.filter(x=>!x.parentId&&x.id!==c?.id),'id','name',c?.parentId,'Kategori utama')))}${field('Ikon','icon',select('icon',['food','shopping','car','home','heart','spark','bank','wallet','coins','receipt','tags'].map(i=>`<option value="${i}" ${i===(c?.icon||'tags')?'selected':''}>${i}</option>`).join('')))}${field('Warna','color',select('color',colors.map(color=>`<option value="${color}" ${color===(c?.color||colors[0])?'selected':''}>${color}</option>`).join('')))}</div>`)}
function modalBook(){const b=ui.modal?.id?state.books.find(x=>x.id===ui.modal.id):null;return modalFrame(b?'Edit buku kas':'Buku kas baru','Pisahkan keuangan berdasarkan kebutuhan.',`<div class="form-grid">${field('Nama buku kas','name',input('name','text',b?.name||'','required'),'span2')}${field('Jenis','type',select('type',[['personal','Pribadi'],['family','Keluarga'],['team','Tim'],['business','Bisnis'],['project','Proyek'],['aa','Patungan AA']].map(([id,label])=>`<option value="${id}" ${id===(b?.type||'personal')?'selected':''}>${label}</option>`).join('')))}${field('Warna','color',select('color',colors.map(color=>`<option value="${color}" ${color===(b?.color||colors[0])?'selected':''}>${color}</option>`).join('')))}</div>`)}
function modalMember(){return modalFrame('Tambah anggota','Anggota lokal untuk alur buku kas dan patungan.',`<div class="form-grid">${field('Nama anggota','name',input('name','text','','required placeholder="Nama anggota"'),'span2')}${field('Peran','role',select('role',`<option value="editor">Editor — dapat mengubah data</option><option value="viewer">Viewer — hanya melihat</option>`),'span2')}</div><div class="notice" style="margin-top:15px">${icon('info')}Penambahan ini belum mengirim undangan. Identitas tersimpan di browser ini saja.</div>`,'Tambah anggota')}
function modalRecurring(){const r=ui.modal?.id?state.recurring.find(x=>x.id===ui.modal.id):null;return modalFrame(r?'Edit jadwal':'Jadwal berulang','Transaksi dibuat saat tanggal jatuh tempo dilewati.',`<div class="form-grid">${field('Nama transaksi','note',input('note','text',r?.note||'','required'),'span2')}${field('Jenis','type',select('type',`<option value="expense" ${r?.type==='expense'?'selected':''}>Pengeluaran</option><option value="income" ${r?.type==='income'?'selected':''}>Pemasukan</option>`))}${field('Jumlah','amount',input('amount','number',r?.amount||'','min="0.01" step="0.01" required'))}${field('Rekening','accountId',select('accountId',opts(accounts(),'id','name',r?.accountId,'Pilih rekening'),'required'))}${field('Kategori','categoryId',select('categoryId',opts(state.categories,'id','name',r?.categoryId,'Pilih kategori'),'required'))}${field('Frekuensi','frequency',select('frequency',[['daily','Harian'],['weekly','Mingguan'],['biweekly','2 mingguan'],['monthly','Bulanan'],['yearly','Tahunan']].map(([id,label])=>`<option value="${id}" ${id===(r?.frequency||'monthly')?'selected':''}>${label}</option>`).join('')))}${field('Jatuh tempo berikutnya','nextDate',input('nextDate','date',r?.nextDate||today(),'required'))}${field('Berakhir (opsional)','endDate',input('endDate','date',r?.endDate||''),'span2')}</div>`)}
function splitMembers(){return state.members.filter(m=>m.bookId===state.activeBookId)}
function splitFields(members){const method=ui.splitMethod;return members.map(m=>`<div class="split-member"><div class="mini-avatar">${esc(m.name.slice(0,2).toUpperCase())}</div><span>${esc(m.name)}</span>${method==='equal'?`<input type="checkbox" name="member-${m.id}" checked aria-label="Sertakan ${esc(m.name)}">`:`<input class="input" type="number" min="0" step="0.01" name="member-${m.id}" value="${esc(ui.splitDraft[m.id]??(method==='weight'?'1':''))}" placeholder="${method==='percent'?'%':method==='weight'?'Porsi':'IDR'}" aria-label="Bagian ${esc(m.name)}">`}</div>`).join('')}
function modalSplit(){const members=splitMembers();return modalFrame('Patungan baru','Pilih pembayar dan cara membagi tagihan.',`<div class="form-grid">${field('Judul','title',input('title','text','','required placeholder="Contoh: Makan malam"'),'span2')}${field('Total tagihan (IDR)','amount',input('amount','number','','min="0.01" step="0.01" required'))}${field('Tanggal','date',input('date','date',today(),'required'))}${field('Dibayar oleh','payerMemberId',select('payerMemberId',opts(members,'id','name',members[0]?.id,'Pilih pembayar'),'required'))}${field('Dari rekening','accountId',select('accountId',opts(accounts(),'id','name',accounts()[0]?.id,'Pilih rekening'),'required'))}</div><div class="divider"></div><div class="field"><label>Metode pembagian</label><div class="segmented">${[['equal','Rata'],['amount','Nominal'],['percent','Persen'],['weight','Porsi']].map(([id,label])=>`<button type="button" data-split-method="${id}" class="${ui.splitMethod===id?'active':''}">${label}</button>`).join('')}</div></div><div id="split-members" style="margin-top:15px">${splitFields(members)}</div>`,'Buat patungan',true)}
function modalSplitDetail(){const s=state.splits.find(x=>x.id===ui.modal.id);if(!s)return '';const shares=splitOwed(s);return modalFrame(s.title,'Rincian bagian dan pelunasan.',`<div class="report-summary" style="grid-template-columns:1fr 1fr"><div><span>Total tagihan</span><strong>${display(s.amount)}</strong></div><div><span>Dibayar oleh</span><strong>${esc(state.members.find(m=>m.id===s.payerMemberId)?.name||'—')}</strong></div></div><div class="divider"></div>${shares.map(sh=>{const m=state.members.find(x=>x.id===sh.memberId),rest=Math.max(0,sh.amount-sh.paid);return `<div class="transaction-row"><div class="mini-avatar">${esc((m?.name||'?').slice(0,2).toUpperCase())}</div><div class="tx-main"><strong>${esc(m?.name||'Anggota')}</strong><small>Bagian ${display(sh.amount)} · Lunas ${display(sh.paid)}</small></div><div class="tx-amount">${display(rest)}</div>${sh.memberId!==s.payerMemberId&&rest>0?`<button type="button" class="btn tiny primary" data-settle="${s.id}:${sh.memberId}">Lunasi</button>`:''}</div>`}).join('')}${s.settlements?.length?`<div class="divider"></div><h3>Riwayat pelunasan</h3>${s.settlements.map(x=>`<div class="stat-row"><span>${fmtDate(x.date)} · ${esc(state.members.find(m=>m.id===x.memberId)?.name||'Anggota')}</span><strong>${display(x.amount)}</strong></div>`).join('')}`:''}`,'Tutup',true)}
function modalSettle(){const [splitId,memberId]=ui.modal.id.split(':'),s=state.splits.find(x=>x.id===splitId),share=splitOwed(s).find(x=>x.memberId===memberId),rest=Math.max(0,share.amount-share.paid);return modalFrame('Catat pelunasan',`${state.members.find(m=>m.id===memberId)?.name||'Anggota'} membayar bagian patungan.`,`<div class="form-grid">${field('Jumlah (IDR)','amount',input('amount','number',rest,'min="0.01" step="0.01" required'))}${field('Tanggal','date',input('date','date',today(),'required'))}${field('Masuk ke rekening','accountId',select('accountId',opts(accounts(),'id','name',s.accountId,'Pilih rekening'),'required'),'span2')}</div>`,'Catat lunas')}
function modalRates(){return modalFrame('Kurs mata uang','Kurs manual terhadap rupiah, untuk tampilan dan konversi transaksi.',`<div class="form-grid">${['USD','EUR','SGD','JPY'].map(c=>field(`1 ${c} = IDR`,c,input(c,'number',state.rates[c],'min="0.0001" step="0.0001" required'))).join('')}${field('Tampilkan saldo dalam','selectedCurrency',select('selectedCurrency',['IDR','USD','EUR','SGD','JPY'].map(c=>`<option value="${c}" ${c===state.selectedCurrency?'selected':''}>${c}</option>`).join('')),'span2')}</div><div class="notice" style="margin-top:15px">${icon('info')}Kurs tidak diperbarui otomatis; laporan memakai kurs manual saat ini.</div>`)}
function modalRestore(){if(!pendingRestore)return '';const {data,exportedAt,fileName}=pendingRestore;return modalFrame('Konfirmasi restore','Periksa file sebelum mengganti data lokal.',`<div class="restore-file-name">${icon('copy',18)}<div><strong>${esc(fileName)}</strong><small>Backup: ${fmtDate(exportedAt.slice(0,10))}</small></div></div><div class="restore-compare"><div><span>Data saat ini</span><strong>${state.books.length} buku kas</strong><small>${state.transactions.length} transaksi</small></div><div class="restore-arrow">${icon('chevron',20)}</div><div><span>Data dari file</span><strong>${data.books.length} buku kas</strong><small>${data.transactions.length} transaksi</small></div></div><div class="notice restore-warning">${icon('info')}Semua data lokal saat ini akan diganti. Tindakan ini tidak dapat dibatalkan tanpa file backup sebelumnya.</div><label class="restore-confirm"><input type="checkbox" name="confirmRestore" required><span>Saya paham data saat ini akan ditimpa.</span></label>`,'Ya, pulihkan data',true)}
function modalConfirm(){const labels={transaction:'transaksi',budget:'anggaran',account:'rekening',category:'kategori',book:'buku kas',recurring:'jadwal',member:'anggota',split:'patungan'};return modalFrame(`Hapus ${labels[ui.modal.targetKind]||'data'}?`,'Tindakan ini tidak dapat dibatalkan.',`<div class="notice" style="background:#ffe1dc">${icon('info')}Pastikan data yang dipilih memang tidak lagi diperlukan.</div>`,'Ya, hapus')}
function renderModal(){if(!ui.modal){$('#modal-layer').innerHTML='';return}const renderers={transaction:modalTransaction,transfer:modalTransfer,budget:modalBudget,account:modalAccount,category:modalCategory,book:modalBook,member:modalMember,recurring:modalRecurring,split:modalSplit,splitDetail:modalSplitDetail,settle:modalSettle,rates:modalRates,restore:modalRestore,confirm:modalConfirm};$('#modal-layer').innerHTML=(renderers[ui.modal.kind]||modalTransaction)();setTimeout(()=>$('.modal input:not([type="hidden"]),.modal select')?.focus(),0)}
function closeModal(){if(ui.modal?.kind==='restore')pendingRestore=null;ui.modal=null;renderModal()}
function downloadBackup(){try{const content=createBackup(state),blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`pitihden-backup-${today()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Backup JSON berhasil dibuat')}catch(error){toast(error.message||'Backup gagal dibuat')}}
async function prepareRestore(file){if(!file)return;try{if(file.size>25*1024*1024)throw new Error('File terlalu besar (maksimum 25 MB).');const parsed=parseBackup(await file.text());pendingRestore={...parsed,fileName:file.name};ui.modal={kind:'restore'};renderModal()}catch(error){pendingRestore=null;toast(error.message||'File backup tidak dapat dibaca')}}
function fail(message){toast(message);return false}
function removeItem(kind,id){
  if(kind==='transaction'){const t=state.transactions.find(x=>x.id===id);if(t?.splitId)return fail('Hapus patungannya terlebih dahulu');state.transactions=state.transactions.filter(x=>x.id!==id)}
  if(kind==='budget')state.budgets=state.budgets.filter(x=>x.id!==id);
  if(kind==='account'){if(state.transactions.some(t=>t.accountId===id||t.toAccountId===id)||state.recurring.some(r=>r.accountId===id))return fail('Rekening masih dipakai transaksi atau jadwal');state.accounts=state.accounts.filter(x=>x.id!==id)}
  if(kind==='category'){if(state.categories.some(c=>c.parentId===id)||state.transactions.some(t=>t.categoryId===id)||state.budgets.some(b=>b.categoryId===id)||state.recurring.some(r=>r.categoryId===id))return fail('Kategori masih dipakai atau memiliki subkategori');state.categories=state.categories.filter(x=>x.id!==id)}
  if(kind==='book'){if(state.books.length===1)return fail('Buku kas terakhir tidak dapat dihapus');if(state.transactions.some(t=>t.bookId===id)||state.accounts.some(a=>a.bookId===id)||state.splits.some(s=>s.bookId===id)||state.recurring.some(r=>r.bookId===id))return fail('Kosongkan rekening, transaksi, jadwal, dan patungan dahulu');state.books=state.books.filter(x=>x.id!==id);state.members=state.members.filter(x=>x.bookId!==id);state.budgets=state.budgets.filter(x=>x.bookId!==id);state.books.forEach(b=>{if(b.familyBookId===id)b.familyBookId=null});if(state.activeBookId===id)state.activeBookId=state.books[0].id}
  if(kind==='recurring')state.recurring=state.recurring.filter(x=>x.id!==id);
  if(kind==='member'){if(state.splits.some(s=>s.shares.some(sh=>sh.memberId===id)))return fail('Anggota masih ada dalam patungan');state.members=state.members.filter(x=>x.id!==id)}
  if(kind==='split'){const s=state.splits.find(x=>x.id===id);if(s){const ids=[s.transactionId,...(s.settlements||[]).map(x=>x.transactionId)];state.transactions=state.transactions.filter(t=>!ids.includes(t.id));state.splits=state.splits.filter(x=>x.id!==id)}}
  save();closeModal();render();toast('Data berhasil dihapus');return true
}
function submitModal(event){event.preventDefault();const form=event.target;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries()),kind=ui.modal.kind,id=ui.modal.id;let item;
  if(kind==='restore'){
    if(!pendingRestore)return fail('Pilih file backup terlebih dahulu');
    const restored=pendingRestore.data;
    try{localStorage.setItem(DATA_KEY,JSON.stringify(restored))}
    catch{return fail('Penyimpanan browser tidak cukup untuk restore')}
    state=restored;pendingRestore=null;ui.modal=null;ui.page='dashboard';ui.period=monthKey(today());
    materializeRecurring();render();toast('Data berhasil dipulihkan dari JSON');return;
  }
  if(kind==='confirm'){removeItem(ui.modal.targetKind,id);return}
  if(kind==='splitDetail'){closeModal();return}
  if(kind==='transaction'||kind==='transfer'){
    const isTransfer=kind==='transfer',type=isTransfer?'transfer':data.type;
    if(!accounts().length)return fail('Buat rekening dahulu');
    if(isTransfer&&data.accountId===data.toAccountId)return fail('Rekening sumber dan tujuan harus berbeda');
    if(!isTransfer&&category(data.categoryId)?.type!==type)return fail('Pilih kategori sesuai jenis transaksi');
    const amount=n(data.amount);if(amount<=0)return fail('Jumlah harus lebih dari nol');
    item=id?state.transactions.find(t=>t.id===id):{id:uid(),bookId:state.activeBookId,createdAt:Date.now()};
    Object.assign(item,{date:data.date,type,amount,currency:isTransfer?(account(data.accountId)?.currency||'IDR'):data.currency,accountId:data.accountId,toAccountId:isTransfer?data.toAccountId:null,categoryId:isTransfer?null:data.categoryId,note:data.note.trim()});
    if(!id)state.transactions.push(item);
  }
  if(kind==='budget'){
    if(state.budgets.some(b=>b.id!==id&&b.bookId===state.activeBookId&&b.month===data.month&&(b.categoryId||'')===data.categoryId))return fail('Anggaran kategori ini sudah ada untuk bulan tersebut');
    item=id?state.budgets.find(b=>b.id===id):{id:uid(),bookId:state.activeBookId};Object.assign(item,{month:data.month,amount:n(data.amount),categoryId:data.categoryId||null});if(!id)state.budgets.push(item)
  }
  if(kind==='account'){
    item=id?account(id):{id:uid(),bookId:state.activeBookId};Object.assign(item,{name:data.name.trim(),type:data.type,currency:data.currency,opening:n(data.opening),color:data.color});if(!id)state.accounts.push(item)
  }
  if(kind==='category'){
    if(data.parentId&&category(data.parentId)?.type!==data.type)return fail('Jenis subkategori harus sama dengan kategori induk');
    item=id?category(id):{id:uid()};Object.assign(item,{name:data.name.trim(),type:data.type,parentId:data.parentId||null,icon:data.icon,color:data.color});if(!id)state.categories.push(item)
  }
  if(kind==='book'){
    item=id?state.books.find(b=>b.id===id):{id:uid(),familyBookId:null,code:`BUKU-${Math.random().toString(36).slice(2,7).toUpperCase()}`};Object.assign(item,{name:data.name.trim(),type:data.type,color:data.color});if(!id){state.books.push(item);state.members.push({id:uid(),bookId:item.id,name:'Saya',role:'owner'});state.activeBookId=item.id}
  }
  if(kind==='member'){if(state.members.some(m=>m.bookId===state.activeBookId&&m.name.toLowerCase()===data.name.trim().toLowerCase()))return fail('Nama anggota sudah ada');state.members.push({id:uid(),bookId:state.activeBookId,name:data.name.trim(),role:data.role})}
  if(kind==='recurring'){
    if(category(data.categoryId)?.type!==data.type)return fail('Kategori tidak sesuai jenis transaksi');
    if(data.endDate&&data.endDate<data.nextDate)return fail('Tanggal akhir sebelum jatuh tempo');
    item=id?state.recurring.find(r=>r.id===id):{id:uid(),bookId:state.activeBookId};Object.assign(item,{note:data.note.trim(),type:data.type,amount:n(data.amount),categoryId:data.categoryId,accountId:data.accountId,frequency:data.frequency,nextDate:data.nextDate,endDate:data.endDate||''});if(!id)state.recurring.push(item);materializeRecurring()
  }
  if(kind==='split'){
    const members=splitMembers(),amount=n(data.amount);if(members.length<2)return fail('Tambahkan setidaknya satu anggota lain');let shares=[];
    if(ui.splitMethod==='equal'){const selected=members.filter(m=>form.querySelector(`[name="member-${m.id}"]`)?.checked);if(!selected.length)return fail('Pilih peserta patungan');const each=Math.floor(amount*100/selected.length)/100;shares=selected.map((m,i)=>({memberId:m.id,amount:i===selected.length-1?Math.round((amount-each*(selected.length-1))*100)/100:each}))}
    else {const values=members.map(m=>({memberId:m.id,value:n(form.querySelector(`[name="member-${m.id}"]`)?.value)})).filter(x=>x.value>0);if(!values.length)return fail('Isi bagian peserta');const sum=values.reduce((a,x)=>a+x.value,0);if(ui.splitMethod==='amount'&&Math.abs(sum-amount)>.01)return fail('Jumlah bagian harus sama dengan total tagihan');if(ui.splitMethod==='percent'&&Math.abs(sum-100)>.01)return fail('Persentase harus berjumlah 100%');let allocated=0;shares=values.map((x,i)=>{const part=i===values.length-1?Math.round((amount-allocated)*100)/100:Math.round((ui.splitMethod==='amount'?x.value:amount*x.value/sum)*100)/100;allocated+=part;return {memberId:x.memberId,amount:part}})}
    if(!shares.some(x=>x.memberId===data.payerMemberId))return fail('Pembayar harus ikut dalam pembagian');
    const txId=uid(),splitId=uid();state.transactions.push({id:txId,bookId:state.activeBookId,date:data.date,type:'expense',amount,currency:'IDR',categoryId:'cat-lifestyle',accountId:data.accountId,toAccountId:null,note:`Patungan: ${data.title.trim()}`,splitId,createdAt:Date.now()});state.splits.push({id:splitId,bookId:state.activeBookId,title:data.title.trim(),date:data.date,amount,payerMemberId:data.payerMemberId,accountId:data.accountId,method:ui.splitMethod,shares,settlements:[],transactionId:txId});ui.splitDraft={}
  }
  if(kind==='settle'){
    const [splitId,memberId]=id.split(':'),s=state.splits.find(x=>x.id===splitId),sh=splitOwed(s).find(x=>x.memberId===memberId),remaining=sh.amount-sh.paid,amount=n(data.amount);if(amount>remaining+.01)return fail('Pelunasan melebihi sisa bagian');const transactionId=uid();s.settlements.push({id:uid(),memberId,amount,date:data.date,transactionId});state.transactions.push({id:transactionId,bookId:s.bookId,date:data.date,type:'income',amount,currency:'IDR',categoryId:'cat-other-in',accountId:data.accountId,toAccountId:null,note:`Pelunasan: ${s.title}`,splitId:s.id,createdAt:Date.now()})
  }
  if(kind==='rates'){for(const c of ['USD','EUR','SGD','JPY'])state.rates[c]=n(data[c]);state.selectedCurrency=data.selectedCurrency}
  save();closeModal();render();toast(id?'Perubahan berhasil disimpan':'Berhasil disimpan')
}
document.addEventListener('click',event=>{
  const el=event.target.closest('button,[data-day]');if(!el)return;
  if(el.dataset.downloadBackup!==undefined){downloadBackup();return}
  if(el.dataset.startFresh!==undefined){state=freshState();ui.page='dashboard';ui.modal=null;save();render();toast('Buku kas kosong siap digunakan');return}
  if(el.dataset.page){ui.page=el.dataset.page;ui.modal=null;render();window.scrollTo({top:0,behavior:'smooth'});return}
  if(el.dataset.modal){ui.modal={kind:el.dataset.modal};if(ui.modal.kind==='transaction')ui.txType='expense';renderModal();return}
  if(el.dataset.edit){const [kind,id]=el.dataset.edit.split(':');ui.modal={kind:kind==='transaction'&&state.transactions.find(t=>t.id===id)?.type==='transfer'?'transfer':kind,id};renderModal();return}
  if(el.dataset.delete){const [targetKind,id]=el.dataset.delete.split(':');ui.modal={kind:'confirm',targetKind,id};renderModal();return}
  if(el.dataset.close!==undefined){closeModal();return}
  if(el.dataset.closeBackdrop!==undefined&&event.target===el){closeModal();return}
  if(el.dataset.switchBook){state.activeBookId=el.dataset.switchBook;save();render();toast('Buku kas diganti');return}
  if(el.dataset.month){const d=new Date(`${ui.calendarMonth}-01T12:00:00`);d.setMonth(d.getMonth()+n(el.dataset.month));ui.calendarMonth=d.toISOString().slice(0,7);render();return}
  if(el.dataset.day){ui.selectedDay=el.dataset.day;render();return}
  if(el.dataset.txtype){ui.txType=el.dataset.txtype;const form=$('#modal-form');if(form){form.querySelector('[name="type"]').value=ui.txType;const catSelect=form.querySelector('[name="categoryId"]');catSelect.innerHTML=opts(state.categories.filter(c=>c.type===ui.txType));$$('[data-txtype]').forEach(b=>b.classList.toggle('active',b.dataset.txtype===ui.txType))}return}
  if(el.dataset.splitMethod){const form=$('#modal-form');splitMembers().forEach(m=>{const v=form.querySelector(`[name="member-${m.id}"]`);if(v&&v.type!=='checkbox')ui.splitDraft[m.id]=v.value});ui.splitMethod=el.dataset.splitMethod;$('#split-members').innerHTML=splitFields(splitMembers());$$('[data-split-method]').forEach(b=>b.classList.toggle('active',b.dataset.splitMethod===ui.splitMethod));return}
  if(el.dataset.viewSplit){ui.modal={kind:'splitDetail',id:el.dataset.viewSplit};renderModal();return}
  if(el.dataset.settle){ui.modal={kind:'settle',id:el.dataset.settle};renderModal();return}
});
document.addEventListener('submit',event=>{if(event.target.id==='modal-form')submitModal(event)});
document.addEventListener('change',event=>{if(event.target.id==='restore-file'){const file=event.target.files?.[0];event.target.value='';void prepareRestore(file)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='global-period'||el.id==='mobile-period'){ui.period=el.value;render()}if(el.id==='active-book'){state.activeBookId=el.value;save();render()}if(el.id==='family-link'){book().familyBookId=el.value||null;save();render();toast('Ruang keluarga diperbarui')}if(el.id==='history-type'){ui.historyType=el.value;render()}if(el.id==='history-category'){ui.historyCategory=el.value;render()}if(el.id==='history-account'){ui.historyAccount=el.value;render()}if(el.id==='history-from'){ui.historyFrom=el.value;render()}if(el.id==='history-to'){ui.historyTo=el.value;render()}if(el.id==='report-period'){ui.reportPeriod=el.value;render()}if(el.id==='report-book'){ui.reportBook=el.value;render()}});
document.addEventListener('input',event=>{if(event.target.id==='history-search'){const cursor=event.target.selectionStart;ui.historySearch=event.target.value;render();const next=$('#history-search');next?.focus();next?.setSelectionRange(cursor,cursor)}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&ui.modal)closeModal()});
render();
function reportsV2(){const period=ui.reportPeriod,ids=ui.reportBook==='all'?state.books.map(b=>b.id):[state.activeBookId],summary=totals(ids,period),entries=breakdown(period,ids);return `${pageHead('Laporan & analisis','Baca pola keuangan untuk mengambil keputusan lebih baik.')}<div class="toolbar"><input id="report-period" class="input" type="month" value="${period}"><select id="report-book" class="select"><option value="active" ${ui.reportBook==='active'?'selected':''}>Buku kas aktif</option><option value="all" ${ui.reportBook==='all'?'selected':''}>Semua buku kas</option></select><button class="btn tiny" data-modal="rates">${icon('exchange')} Kurs mata uang</button></div><div class="report-summary"><div><span>Pemasukan</span><strong class="strong-green">${display(summary.income)}</strong></div><div><span>Pengeluaran</span><strong class="strong-red">${display(summary.expense)}</strong></div><div><span>Arus kas bersih</span><strong>${display(summary.income-summary.expense)}</strong></div></div><div class="grid two-col section-gap">${chartCard(period,ids)}${donutCard(period,ids)}</div><div class="grid two-col section-gap"><div class="card card-pad"><div class="card-head"><h2>Pengeluaran per kategori</h2><span class="chip">${esc(fmtMonth(period))}</span></div>${entries.length?entries.map(e=>`<div class="stat-row"><span>${esc(e.c?.name||'Lainnya')}</span><strong>${display(e.amount)}</strong></div>`).join(''):empty('Belum ada data','Pengeluaran akan tampil di sini.')}</div><div class="card card-pad"><div class="card-head"><h2>Ringkasan rekening</h2><span class="chip">${ids.length} buku kas</span></div>${state.accounts.filter(a=>ids.includes(a.bookId)).map(a=>`<div class="stat-row"><span>${esc(a.name)} · ${esc(state.books.find(b=>b.id===a.bookId)?.name||'')}</span><strong>${display(balance(a.id))}</strong></div>`).join('')}</div></div>`}
